package com.adesa.attendance.vendor;
import static com.adesa.attendance.vendor.VendorRules.*;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;
import com.adesa.attendance.security.AuthenticatedEmployee;import com.adesa.attendance.employee.EmployeeRole;
import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional
public class VendorAdmin {
 private final VendorService s;
 public VendorAdmin(VendorService s){this.s=s;}
 public AuthenticatedEmployee administrator(){var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||!auth.isAuthenticated()||!(auth.getPrincipal() instanceof AuthenticatedEmployee p)||p.role()!=EmployeeRole.ADMIN||auth.getAuthorities().stream().noneMatch(a->a.getAuthority().equals("ROLE_ADMIN")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Vendor Management is restricted to the System Administrator.");s.available();s.context("access","ADMIN");return (AuthenticatedEmployee)auth.getPrincipal();}
 public Map<String,Object> overview(){administrator();var rows=applications();var counts=new LinkedHashMap<String,Long>();for(String status:STATUSES)counts.put(status,rows.stream().filter(a->status.equals(a.get("status"))).count());return Map.of("total",rows.size(),"statuses",counts,"verifiedBanking",rows.stream().filter(a->"VERIFIED".equals(a.get("banking_status"))).count(),"applications",rows,"subsidiaries",s.sites(),"demo",s.isDemo());}
 public List<Map<String,Object>> applications(){administrator();return s.jdbc().queryForList("select * from vendor_private.application order by submitted_at desc limit 2000").stream().map(a->{var out=new LinkedHashMap<>(a);var r=s.revision((UUID)a.get("id"),((Number)a.get("current_revision")).intValue());var data=s.unpack((byte[])r.get("payload_cipher"),"revision:"+r.get("id"));for(String key:List.of("businessName","contactName","contactEmail","contactPhone","categories"))out.put(key,data.get(key));out.remove("duplicate_ids");out.put("possibleDuplicates",((java.sql.Array)a.get("duplicate_ids"))!=null?arrayLength(a.get("duplicate_ids")):0);out.put("eligibleForPayment","APPROVED".equals(a.get("status"))&&"VERIFIED".equals(a.get("banking_status")));return (Map<String,Object>)out;}).toList();}
 private static int arrayLength(Object value){try{return ((Object[])((java.sql.Array)value).getArray()).length;}catch(Exception e){return 0;}}
 public Map<String,Object> profile(UUID id,int revision){administrator();var a=s.one("select * from vendor_private.application where id=?",id);int number=revision<=0?((Number)a.get("current_revision")).intValue():revision;var r=s.revision(id,number);var out=new LinkedHashMap<>(a);out.remove("duplicate_ids");out.put("answers",s.unpack((byte[])r.get("payload_cipher"),"revision:"+r.get("id")));out.put("categories",((Map<?,?>)out.get("answers")).get("categories"));out.put("revision",number);out.put("revisions",s.jdbc().queryForList("select number,submitted_at,form_version,content_hash from vendor_private.revision where application_id=? order by number",id));out.put("documents",s.jdbc().queryForList("select d.id,d.category,d.filename,d.mime_type,d.expected_size,d.content_hash,d.created_at,d.ready from vendor_private.document d where d.session_id=? order by d.created_at",r.get("session_id")));out.put("notes",s.jdbc().queryForList("select * from vendor_private.note where application_id=? order by created_at desc",id).stream().map(n->Map.of("id",n.get("id"),"createdAt",n.get("created_at"),"author",n.get("created_by"),"body",new String(s.crypt().open((byte[])n.get("body_cipher"),"note:"+n.get("id")),StandardCharsets.UTF_8))).toList());out.put("history",s.jdbc().queryForList("select * from vendor_private.audit where application_id=? order by id desc",id).stream().map(h->Map.of("id",h.get("id"),"action",h.get("action"),"actor",h.get("actor"),"createdAt",h.get("created_at"),"detail",s.unpack((byte[])h.get("detail_cipher"),"audit:"+h.get("action")))).toList());out.put("requests",s.jdbc().queryForList("select id,created_at,expires_at,consumed_at,created_by from vendor_private.request where application_id=? order by created_at desc",id));out.put("eligibleForPayment","APPROVED".equals(a.get("status"))&&"VERIFIED".equals(a.get("banking_status")));out.put("relatedApplications",s.jdbc().queryForList("select id,reference,subsidiary,status from vendor_private.application where entity_id=? and id<>?",a.get("entity_id"),id));
 var duplicates=s.jdbc().queryForList("select distinct b.application_id from vendor_private.duplicate_index a join vendor_private.duplicate_index b on a.kind=b.kind and a.fingerprint=b.fingerprint where a.application_id=? and b.application_id<>?",id,id);out.put("possibleDuplicates",duplicates.stream().map(d->s.one("select id,reference,subsidiary,status from vendor_private.application where id=?",d.get("application_id"))).toList());return out;}
 public List<Map<String,Object>> links(){administrator();return s.jdbc().queryForList("select * from vendor_private.link order by created_at desc").stream().map(l->{var out=new LinkedHashMap<>(l);String token=new String(s.crypt().open((byte[])out.remove("token_cipher"),"link:"+l.get("id")),StandardCharsets.UTF_8);out.remove("token_hash");out.remove("invited_email_hash");out.put("url",s.page(String.valueOf(l.get("subsidiary")))+"#invite="+token);return (Map<String,Object>)out;}).toList();}
 public Map<String,Object> createLink(Map<String,Object> data){var actor=administrator();String site=text(data.get("subsidiary"),20),kind=text(data.get("kind"),16),label=text(data.get("label"),160);check(SITES.contains(site)&&Set.of("REUSABLE","INVITATION").contains(kind)&&!label.isBlank(),"Choose a subsidiary, link type and label.");String mail=text(data.get("email"),254);if(!mail.isBlank())mail=email(mail);if(s.isDemo()&&!mail.isBlank())check(mail.endsWith(".test"),"Use fictional .test invitation email addresses.");Instant expiry=null;if(data.get("expiresAt")!=null&&!String.valueOf(data.get("expiresAt")).isBlank()){expiry=Instant.parse(String.valueOf(data.get("expiresAt")));check(expiry.isAfter(Instant.now()),"Choose a future expiry date.");}UUID id=UUID.randomUUID();String token=s.crypt().token();s.jdbc().update("insert into vendor_private.link(id,subsidiary,label,kind,token_hash,token_cipher,invited_email_hash,expires_at,created_by) values(?,?,?,?,?,?,?,?,?)",id,site,label,kind,s.crypt().hash(token),s.crypt().seal(token.getBytes(StandardCharsets.UTF_8),"link:"+id),mail.isBlank()?null:s.crypt().fingerprint(mail),expiry==null?null:java.sql.Timestamp.from(expiry),actor.email());s.audit(null,actor.email(),"LINK_CREATED",Map.of("id",id,"subsidiary",site,"kind",kind));return Map.of("id",id,"url",s.page(site)+"#invite="+token);}
 public void linkState(UUID id,String state){var actor=administrator();check(Set.of("ACTIVE","INACTIVE","REVOKED").contains(state),"Choose a valid link status.");var link=s.one("select * from vendor_private.link where id=? for update",id);check(link.get("revoked_at")==null,"Revoked links cannot be reactivated. Generate a new link.");s.jdbc().update("update vendor_private.link set active=?,revoked_at=case when ? then now() else null end where id=?",state.equals("ACTIVE"),state.equals("REVOKED"),id);s.audit(null,actor.email(),"LINK_"+state,Map.of("id",id));}
 public void status(UUID id,String status,String reason){var actor=administrator();check(STATUSES.contains(status),"Choose a valid application status.");if(Set.of("REJECTED","SUSPENDED","ARCHIVED").contains(status))check(!reason.isBlank(),"A reason is required for rejection, suspension or archiving.");var app=s.one("select * from vendor_private.application where id=? for update",id);s.jdbc().update("update vendor_private.application set status=?,updated_at=now() where id=?",status,id);s.audit(id,actor.email(),"STATUS_CHANGED",Map.of("from",app.get("status"),"to",status,"reason",text(reason,5000)));var r=s.revision(id,((Number)app.get("current_revision")).intValue());var payload=s.unpack((byte[])r.get("payload_cipher"),"revision:"+r.get("id"));s.queue(id,String.valueOf(payload.get("contactEmail")),"ADESA vendor application update","Application "+app.get("reference")+"\nCurrent status: "+status.replace('_',' ')+"\n"+(reason.isBlank()?"You will be contacted if further information is needed.":reason),false);}
 public void banking(UUID id,String state,String reason){var actor=administrator();check(Set.of("VERIFIED","UNVERIFIED","REJECTED").contains(state)&&!reason.isBlank(),"Choose a verification outcome and record independent verification evidence.");var a=s.one("select * from vendor_private.application where id=? for update",id);var r=s.revision(id,((Number)a.get("current_revision")).intValue());var data=s.unpack((byte[])r.get("payload_cipher"),"revision:"+r.get("id"));check(!String.valueOf(data.get("accountNumber")).isBlank(),"Banking information has not been provided. Request a signed amendment first.");s.jdbc().update("update vendor_private.application set banking_status=?,banking_verified_by=?,banking_verified_at=case when ? then now() else null end,updated_at=now() where id=?",state,actor.email(),state.equals("VERIFIED"),id);s.audit(id,actor.email(),"BANKING_VERIFICATION",Map.of("status",state,"evidence",text(reason,3000)));}
 public void note(UUID id,String body){var actor=administrator();s.one("select id from vendor_private.application where id=?",id);check(!body.isBlank(),"Enter a verification note.");UUID note=UUID.randomUUID();s.jdbc().update("insert into vendor_private.note values(?,?,?,?,now())",note,id,s.crypt().seal(text(body,5000).getBytes(StandardCharsets.UTF_8),"note:"+note),actor.email());s.audit(id,actor.email(),"NOTE_ADDED",Map.of("note",note));}
 public Map<String,Object> request(UUID id,String message,int days){var actor=administrator();check(!message.isBlank()&&days>=1&&days<=90,"Describe the requested information and choose a 1–90 day expiry.");var a=s.one("select * from vendor_private.application where id=? for update",id);UUID request=UUID.randomUUID();String token=s.crypt().token();s.jdbc().update("insert into vendor_private.request(id,application_id,token_hash,token_cipher,message_cipher,expires_at,created_by) values(?,?,?,?,?,?,?)",request,id,s.crypt().hash(token),s.crypt().seal(token.getBytes(StandardCharsets.UTF_8),"request-token:"+request),s.crypt().seal(text(message,5000).getBytes(StandardCharsets.UTF_8),"request:"+request),java.sql.Timestamp.from(Instant.now().plus(Duration.ofDays(days))),actor.email());s.jdbc().update("update vendor_private.application set status='ADDITIONAL_INFORMATION_REQUIRED',updated_at=now() where id=?",id);String url=s.page(String.valueOf(a.get("subsidiary")))+"#request="+token;var r=s.revision(id,((Number)a.get("current_revision")).intValue());var data=s.unpack((byte[])r.get("payload_cipher"),"revision:"+r.get("id"));s.queue(id,String.valueOf(data.get("contactEmail")),"ADESA: additional vendor information requested","Application "+a.get("reference")+"\n"+message+"\nUse this secure link: "+url+"\nYou must review and sign a new revision. Previous signed submissions are preserved.",false);s.audit(id,actor.email(),"INFORMATION_REQUESTED",Map.of("request",request,"message",message,"days",days));return Map.of("url",url);}
 public void associate(UUID id,UUID related){var actor=administrator();check(!id.equals(related),"Choose another application.");var a=s.one("select * from vendor_private.application where id=?",related);s.jdbc().update("update vendor_private.application set entity_id=? where id=?",a.get("entity_id"),id);s.audit(id,actor.email(),"RELATED_VENDOR",Map.of("relatedApplication",related));}
 public List<Map<String,Object>> notices(){var actor=administrator();return s.jdbc().queryForList("select n.*,a.reference from vendor_private.notice n join vendor_private.application a on a.id=n.application_id where n.recipient_id=? order by n.created_at desc limit 100",actor.employeeId());}
 public void readNotice(UUID id){var actor=administrator();s.jdbc().update("update vendor_private.notice set read_at=now() where id=? and recipient_id=?",id,actor.employeeId());}
 public Map<String,Object> documentTicket(UUID id){var actor=administrator();var d=s.one("select * from vendor_private.document where id=? and application_id is not null and ready",id);String token=s.crypt().token();s.jdbc().update("insert into vendor_private.download values(?,?,?,?,null)",s.crypt().hash(token),id,actor.employeeId(),java.sql.Timestamp.from(Instant.now().plusSeconds(90)));s.audit((UUID)d.get("application_id"),actor.email(),"DOCUMENT_ACCESS_GRANTED",Map.of("document",id));return Map.of("ticket",token,"expiresIn",90);}
 public Map<String,Object> download(String token){var actor=administrator();var ticket=s.one("select * from vendor_private.download where token_hash=? and employee_id=? and consumed_at is null and expires_at>now() for update",s.crypt().hash(token),actor.employeeId());s.jdbc().update("update vendor_private.download set consumed_at=now() where token_hash=?",s.crypt().hash(token));var d=s.one("select * from vendor_private.document where id=?",ticket.get("document_id"));s.audit((UUID)d.get("application_id"),actor.email(),"DOCUMENT_DOWNLOADED",Map.of("document",d.get("id")));return Map.of("bytes",s.crypt().open((byte[])d.get("body_cipher"),"document:"+d.get("id")),"mime",d.get("mime_type"),"filename",d.get("filename"));}
 public byte[] pdf(UUID id,int number){var actor=administrator();var profile=profile(id,number<=0?1:number);var answers=(Map<String,Object>)profile.get("answers");UUID signature=UUID.fromString(String.valueOf(answers.get("signatureId")));var d=s.one("select * from vendor_private.document where id=? and application_id=?",signature,id);byte[] image=s.crypt().open((byte[])d.get("body_cipher"),"document:"+signature);byte[] pdf=VendorPdf.write(profile,image);s.audit(id,actor.email(),"PDF_EXPORTED",Map.of("revision",profile.get("revision")));return pdf;}
 public Map<String,Object> mailPreview(){administrator();return Map.of("messages",s.jdbc().queryForList("select id,application_id,subject,internal,state,created_at,delivered_at from vendor_private.outbox order by created_at desc limit 100"));}
}
